import boto3

def translate_text(text, source_language_code, target_language_code):
    client = boto3.client('translate')
    result = client.translate_text(Text=text, SourceLanguageCode=source_language_code, TargetLanguageCode=target_language_code)
    return result.get('TranslatedText')

if __name__ == '__main__':
    platform_output = 'This is the platform model output.'
    translated_output = translate_text(platform_output, 'en', 'es')
    print(translated_output)

import boto3

def check_unsafe_content(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_toxic_content(
        TextSegments=[
            {
                'Text': text
            }
        ]
    )
    return response

if __name__ == '__main__':\n    text_to_check = 'Example text to check for unsafe content.'
    result = check_unsafe_content(text_to_check)
    print(result)

from amazon.bedrock.client import Bedrock

class ModelRequest:
    def __init__(self, model_id, input_text):
        self.model_id = model_id
        self.input_text = input_text

    def to_dict(self):
        return {
            'modelId': self.model_id,
            'inputText': self.input_text
        }

class ModelResponse:
    def __init__(self, output_text):
        self.output_text = output_text

    @staticmethod
    def from_dict(response_dict):
        return ModelResponse(response_dict['outputText'])

class ModelNormalizer:
    @staticmethod
    def normalize(response):
        return response.output_text.strip().capitalize()

import boto3

def collect_platform_metadata():
    bedrock_client = boto3.client('bedrock', region_name='us-west-2')
    response = bedrock_client.invoke_model(
        model_id='amazon.titan-text-express-v1',
        body={
            'inputText': 'Hello, world!'
        }
    )
    model_output = response['body'].read()
    usage = response['usage']
    resource_id = response['responseMetadata']['RequestId']
    return {
        'model_output': model_output,
        'usage': usage,
        'resource_id': resource_id
    }

if __name__ == '__main__':
    metadata = collect_platform_metadata()
    print(metadata)

import boto3

def stream_platform_generation():
    bedrock = boto3.client('bedrock-runtime')
    response = bedrock.invoke_model(
        modelId='amazon.titan-text-express-v1',
        body={
            'inputText': 'Hello, world!',
            'textGenerationConfig': {
                'maxTokenCount': 200,
                'stopSequences': [],
                'temperature': 0.5,
                'topP': 0.9
            }
        }
    )
    response_body = response['body'].read()
    response_text = response_body.decode('utf-8')
    print(response_text)

    return response
